css:
.media {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  max-width: 480px;
  padding: 16px;
}

.thumb {
  flex-shrink: 0;
  width: 96px;
  height: 96px;
  object-fit: cover;
  border-radius: 6px;
}

.body {
  flex: 1;
  min-width: 0;
}

.title {
  margin: 0 0 4px;
  font-weight: 600;
}

.text {
  margin: 0;
  color: #52525b;
}
